<script setup lang="ts">
import { onMounted, onUnmounted, ref, watch } from 'vue';
import { LoaderCircle, RefreshCw } from 'lucide-vue-next';
import { useApi, isCancelled, onSessionExpired, onAccessDenied } from '../lib/api';
import { operationID, stamp } from '../lib/commerce';
import { cryptoOperationsSupported, type CryptoSettings } from '../lib/cryptoPayments';
import { canAllocate, type CryptoWallet } from '../lib/cryptoWallet';
import { t } from '../i18n';
import { usePaymentModule } from '../lib/paymentModule';
const props=withDefaults(defineProps<{wallets:CryptoWallet[];active?:boolean}>(),{active:true});
const {enabled:moduleEnabled}=usePaymentModule(()=>props.active);
const api=useApi('/commerce/crypto/admin'),settings=ref<CryptoSettings>(),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),password=ref('');
let disposed=false,sequence=0,pending:{key:string;id:string}|undefined;
async function load(){if(!props.active)return;const current=++sequence;loading.value=true;try{const v=await api<CryptoSettings>('/settings');if(!disposed&&current===sequence&&props.active){settings.value=v;pending=undefined}}catch(reason){if(!disposed&&!isCancelled(reason))error.value=t((reason as Error).message)}finally{if(current===sequence)loading.value=false}}
async function save(){if(!settings.value||busy.value)return;if(settings.value.enabled&&!moduleEnabled.value){error.value=t('支付模块已关闭，请先启用支付模块。');return}busy.value=true;error.value='';notice.value='';const value=JSON.parse(JSON.stringify(settings.value)),key=JSON.stringify(value);if(pending?.key!==key)pending={key,id:operationID()};try{const v=await api<CryptoSettings>('/settings','POST',{...value,password:password.value,operation_id:pending.id});if(!disposed&&props.active){settings.value=v;pending=undefined;notice.value=t('加密货币付款设置已保存')}}catch(reason){if(!disposed&&!isCancelled(reason))error.value=t((reason as Error).message)}finally{password.value='';busy.value=false}}
const clear=()=>{password.value='';settings.value=undefined;sequence++};const unsub=onSessionExpired(clear),unsubAccess=onAccessDenied(clear);
watch(()=>props.active,active=>{password.value='';if(active)void load();else sequence++});onMounted(()=>{void load()});onUnmounted(()=>{disposed=true;sequence++;password.value='';unsub();unsubAccess()});
function dateInput(value:number){if(!value)return '';const d=new Date(value*1000);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function setExpiry(id:string,event:Event){const asset=settings.value?.assets.find(a=>a.id===id);if(asset){const date=Date.parse((event.target as HTMLInputElement).value);asset.rate_expires_at=Number.isFinite(date)?Math.floor(date/1000):0}}
</script>
<template>
<details class="crypto-payment-settings"><summary>{{t('收款配置')}}<span>{{settings?.enabled?t('已开放加密货币付款'):t('未开放加密货币付款')}}</span></summary><div class="crypto-config-body"><div class="crypto-config-heading"><p>{{t('用户选择加密货币付款后，系统自动分配专属地址。付款最终确认后自动开通套餐。')}}</p><button type="button" :disabled="busy||loading" @click="load"><RefreshCw :size="15"/>{{t('刷新')}}</button></div><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><p v-if="loading&&!settings" role="status">{{t('加载中…')}}</p><form v-if="settings" @submit.prevent="save"><fieldset :disabled="busy||loading"><label class="crypto-check"><input v-model="settings.enabled" type="checkbox" :disabled="!moduleEnabled&&!settings.enabled"/>{{t('开放加密货币套餐付款')}}</label><div class="crypto-config-grid"><label>{{t('收款钱包')}}<select v-model="settings.wallet_id" :required="settings.enabled"><option value="">{{t('请选择钱包')}}</option><option v-for="wallet in wallets" :key="wallet.id" :value="wallet.id" :disabled="!canAllocate(wallet)">{{wallet.name}} · {{wallet.mode==='hot'?t('面板热钱包'):t('外部 xpub · 只读')}}{{canAllocate(wallet)?'':' · '+t('暂不可用')}}</option></select></label><label>{{t('付款报价有效期 / 分钟')}}<input v-model.number="settings.invoice_minutes" type="number" min="15" max="120" required/></label></div><details v-for="chain in settings.chains" :key="chain.id" class="crypto-network-config"><summary>{{chain.name}} <span>{{chain.native_symbol}} · {{chain.enabled?t('已启用'):t('未启用')}}</span></summary><div class="crypto-config-grid"><label class="crypto-check"><input v-model="chain.enabled" type="checkbox" :disabled="!cryptoOperationsSupported(chain.chain_id)"/>{{t('允许此网络收款')}}</label><p v-if="!cryptoOperationsSupported(chain.chain_id)" class="crypto-config-note">{{t('此网络尚未完成最终性验证，当前仅可查询余额。')}}</p><label>{{t('主 RPC 地址')}}<input v-model.trim="chain.rpc_url" type="url" autocomplete="off" :placeholder="chain.has_rpc?t('已配置，留空保持不变'):'https://…'"/></label><label>{{t('备用 RPC 地址')}}<input v-model.trim="chain.rpc_backup_url" type="url" autocomplete="off" :placeholder="chain.has_rpc_backup?t('已配置，留空保持不变'):'https://…'"/></label><p class="crypto-config-note wide">{{t('开启收款前，系统会检查两个 RPC 的网络与最终确认区块。RPC 中的密钥保存后不再回显。')}}</p></div><div v-for="asset in settings.assets.filter(a=>a.chain_id===chain.chain_id)" :key="asset.id" class="crypto-asset-config"><label class="crypto-check"><input v-model="asset.enabled" type="checkbox" :disabled="!cryptoOperationsSupported(chain.chain_id)"/>{{asset.symbol}} · {{asset.name}}</label><p class="crypto-contract">{{asset.contract}}</p><div class="crypto-config-grid"><label>{{t('手动汇率 / 元每枚')}}<input v-model.trim="asset.cny_per_token" inputmode="decimal" :required="asset.enabled"/></label><label>{{t('汇率有效至')}}<input :value="dateInput(asset.rate_expires_at)" type="datetime-local" :required="asset.enabled" @input="setExpiry(asset.id,$event)"/></label><label>{{t('付款小数位数')}}<input v-model.number="asset.payment_decimals" type="number" min="0" :max="asset.decimals" required/></label><p class="crypto-config-note">{{t('最近更新')}} {{asset.rate_updated_at?stamp(asset.rate_updated_at):'—'}}</p></div></div></details><p class="crypto-config-note">{{t('汇率由管理员手动设置，并非实时市场汇率。到期后停止创建新付款单，已有付款单保留原报价。')}}</p><label>{{t('管理员当前密码')}}<input v-model="password" type="password" required autocomplete="current-password"/></label><button type="submit" class="primary"><LoaderCircle v-if="busy" :size="16" class="spin"/>{{busy?t('保存中…'):t('保存收款配置')}}</button></fieldset></form></div></details>
</template>
<style scoped>
.crypto-payment-settings{border:1px solid var(--border);border-radius:12px;font-size:13px;min-width:0}.crypto-payment-settings>summary{display:flex;justify-content:space-between;gap:12px;padding:18px;cursor:pointer;font-weight:600}.crypto-payment-settings summary span{font-size:12px;font-weight:400;color:var(--secondary)}.crypto-config-body{padding:0 18px 18px;display:grid;gap:14px}.crypto-config-heading{display:flex;align-items:flex-start;gap:14px;justify-content:space-between}.crypto-config-heading p{font-size:12px;line-height:1.8;color:var(--secondary);margin:0}.crypto-config-heading button{flex-shrink:0}.crypto-payment-settings fieldset{border:0;padding:0;margin:0;display:grid;gap:18px;min-width:0}.crypto-payment-settings label{display:grid;gap:8px;margin:0;min-width:0;font-size:12px}.crypto-payment-settings label input,.crypto-payment-settings label select{width:100%;min-height:44px;min-width:0}.crypto-payment-settings .crypto-check{display:flex;align-items:center;gap:9px}.crypto-check input{width:17px!important;min-height:17px!important;flex-shrink:0}.crypto-config-grid{display:grid;grid-template-columns:1fr 1fr;gap:15px;min-width:0}.crypto-config-grid .wide{grid-column:1/-1}.crypto-network-config{padding:15px;border:1px solid var(--border);border-radius:10px;min-width:0}.crypto-network-config summary{cursor:pointer;line-height:1.8}.crypto-network-config>.crypto-config-grid{margin-top:17px}.crypto-asset-config{padding-top:16px;margin-top:16px;border-top:1px solid var(--border)}.crypto-config-note,.crypto-contract{font-size:12px;color:var(--secondary);line-height:1.8;margin:0;overflow-wrap:anywhere}.crypto-contract{font-family:monospace;margin:9px 0 13px}.crypto-payment-settings .primary{justify-self:start;min-height:44px}@media(max-width:600px){.crypto-config-grid{grid-template-columns:1fr}.crypto-payment-settings>summary{flex-direction:column;gap:6px}.crypto-config-body{padding:0 14px 14px}.crypto-network-config{padding:12px}}
</style>
